/** static void ContestAICmd_check_combo_starter(void) */
export function ContestAICmd_check_combo_starter(): any {
  let result: any = 0;
      let i: any = null;
      let move: any = gContestMons[eContestAI.contestantId].moves[eContestAI.nextMoveIndex];

      for (i = 0; i < MAX_MON_MOVES; i++)
      {
          if (gContestMons[eContestAI.contestantId].moves[i])
          {
              result = AreMovesContestCombo(move, gContestMons[eContestAI.contestantId].moves[i]);
              if (result)
              {
                  result = 1;
                  break;
              }
          }
      }

      if (result)
          result = 1;

      eContestAI.scriptResult = result;
      gAIScriptPtr += 1;
}

